import{_ as p,a0 as i,w as o,s,ao as l,I as a,x as e,a1 as n,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"Ubuntu每日小貼士 - 在Ubuntu下創建虛擬網卡 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu每日小貼士 - 在Ubuntu下創建虛擬網卡 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu每日小貼士 - 在Ubuntu下創建虛擬網卡 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu每日小貼士 - 在Ubuntu下創建虛擬網卡 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Daily Ubuntu Tips – Create Virtual Network Cards In Ubuntu Linux","title":"Ubuntu每日小貼士 - 在Ubuntu下創建虛擬網卡","tag":"201311","desc":""},"relativePath":"201311/Daily Ubuntu Tips – Create Virtual Network Cards In Ubuntu Linux.md","filePath":"[post].md"}'),b={name:"201311/Daily Ubuntu Tips – Create Virtual Network Cards In Ubuntu Linux.md"};function d(w,t,T,m,C,U){const u=i("Link");return o(),s("div",null,[t[11]||(t[11]=l(`<h1 id="ubuntu每日小貼士-在ubuntu下創建虛擬網卡" tabindex="-1">Ubuntu每日小貼士 - 在Ubuntu下創建虛擬網卡 <a class="header-anchor" href="#ubuntu每日小貼士-在ubuntu下創建虛擬網卡" aria-label="Permalink to “Ubuntu每日小貼士 - 在Ubuntu下創建虛擬網卡”">​</a></h1><p>這個教程是為那些想用Ubuntu做點小實驗的用户準備的。這並不適用於所有人，尤其是那些在（正式環境中）使用生產機器的用户。</p><p>如果你對網絡運行和IP網絡有所瞭解，你應該知道在大多數情況下，每個網卡只會分配一個IP地址。我們習慣認為這是一對一的事物。</p><p>一個網卡對應一個IP地址，你在一台機器上的一個網卡及其IP地址只能綁定或運行單一的網絡服務/端口。例如，如果你想在80端口運行一個web服務器，而一個IP地址和端口號只能由一個web服務器監聽。這是這樣設計的。</p><p>所以，網卡和IP地址並不是一對一的關係，你可以創建可以單獨分配IP地址的虛擬網卡。因此，單一的物理網卡可以羣集無限的子網卡或虛擬網卡。每一個都能分配它自己IP地址到對應的端口。</p><p>這個簡短的教程將展示給你如何在Ubuntu上做到這些。這是在一台電腦上用一張物理網卡和單一的端口號運行及測試多個網絡服務的好方式。</p><p>動手吧，運行下列命令打開網絡接口文件。</p><pre><code>sudo gedit /etc/network/interfaces
</code></pre><p>然後按照下圖中的步驟，添加你想要的任意多的虛擬網卡。默認情況下，Linux會給第一張網卡分配eth0的名稱，所以如果你的機子只有一張網卡，那麼它會被命名為eth0。</p><p>添加虛擬網卡，創建多個靜態網卡並命名為eth0:1、eth0:2、eth0:3等等(eth0後面緊跟冒號和數字)。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/11/virtualnetworkcardubuntu.png" alt=""></p><p>對於你創建的每一個網卡，也要確保網絡都是不同的子網，這是網絡常識（譯註：事實上並非如此，虛擬網卡完全可以是相同子網的IP地址，只要你需要）</p><p>完成以後，保存文件並用下列命令重啓網絡服務。</p><pre><code>sudo service networking restart
</code></pre><p>就是這樣!</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/11/virtualnetworkcardubuntu1.png" alt=""></p><p>玩得開心!</p><hr>`,18)),a("p",null,[t[1]||(t[1]=e("via: ",-1)),n(u,{href:"http://www.liberiangeek.net/2013/11/daily-ubuntu-tips-create-virtual-network-cards-in-ubuntu-linux/"},{default:r(()=>[...t[0]||(t[0]=[e("http://www.liberiangeek.net/2013/11/daily-ubuntu-tips-create-virtual-network-cards-in-ubuntu-linux/",-1)])]),_:1})]),a("p",null,[t[4]||(t[4]=e("譯者：",-1)),n(u,{href:"https://github.com/Luoxcat"},{default:r(()=>[...t[2]||(t[2]=[e("Luoxcat",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),n(u,{href:"https://github.com/wxy"},{default:r(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[8]||(t[8]=e("本文由 ",-1)),n(u,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),n(u,{href:"http://linux.cn/"},{default:r(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const g=p(b,[["render",d]]);export{k as __pageData,g as default};
